            },
            {
              id: GROUP_ID_3,
              attributes: [],
              subGroups: [],
            },
          ],
        },
        {
          id: GROUP_ID_5,
          attributes: [],
          subGroups: [{ id: GROUP_ID_4, attributes: [], subGroups: [] }],
        },
        {
          id: GROUP_ID_6,
          attributes: [],
          subGroups: [
            {
              id: GROUP_ID_7,
              attributes: [],
              subGroups: [],
            },
          ],
        },
      ];
      expect(
        classUnderTest['getFirstGroupWithAttributesForList'](groups, false)
      ).toBeUndefined();
    });
  });
});

