      "@spartacus/setup/ssr": [
        "core-libs/setup/ssr/public_api"
      ],
      "@spartacus/asm/assets": [
        "feature-libs/asm/assets/public_api"
      ],
      "@spartacus/asm/components": [
        "feature-libs/asm/components/public_api"
      ],
      "@spartacus/asm/core": [
        "feature-libs/asm/core/public_api"
      ],
